(5695732, 828661, 5364, '<td valign="top">I feel you have the subjects in the top and bottom frames in the centre and the subject in the middle frame off to the right, so I wonder if you would have been better with either the top or bottom frame having it''s subject off to the left to balance the composition. Otherwise it''s excellent</td>', 'I feel you have the subjects in the top and bottom frames in the centre and the subject in the middle frame off to the right, so I wonder if you would have been better with either the top or bottom frame having it''s subject off to the left to balance the composition. Otherwise it''s excellent', '2009-10-21 14:08:12.000000', NULL, 1),
(5695733, 828732, 100820, '<td valign="top">nice captures, but it seems very overexposed to me.</td>', 'nice captures, but it seems very overexposed to me.', '2009-10-21 14:08:22.000000', NULL, 1),
(5695737, 828412, 100820, '<td valign="top">i wish there was more of an obvious break in between the images - they all seem to blend into one and i find it hard to see the edge of each image (and not in a good-for-a-triptych way).  great colors!</td>', 'i wish there was more of an obvious break in between the images - they all seem to blend into one and i find it hard to see the edge of each image (and not in a good-for-a-triptych way).  great colors!', '2009-10-21 14:09:44.000000', NULL, 1),
