(5695847, 827994, 69668, '<td valign="top">Ha....great image and ''story''.</td>', 'Ha....great image and ''story''.', '2009-10-21 15:01:00.000000', NULL, 1),
(5695879, 828240, 43463, '<td valign="top">The slight sepia tones really complement the ol''tyme feel of this photo composition of a general store. One notices the rough feel of the boards, the textures of the place touched by time...I can almost see and breathe in the dust that was kicked up by my intrusion on a place that time has passed by. Love the grouping of items showing off detail of the place in small that you show us on the left. The right panel then shows off the full view of the store - what was once the hub of the place where all transactions must have taken place.</td>', 'The slight sepia tones really complement the ol''tyme feel of this photo composition of a general store. One notices the rough feel of the boards, the textures of the place touched by time...I can almost see and breathe in the dust that was kicked up by my intrusion on a place that time has passed by. Love the grouping of items showing off detail of the place in small that you show us on the left. The right panel then shows off the full view of the store - what was once the hub of the place where all transactions must have taken place.', '2009-10-21 15:20:27.000000', NULL, 1),
(5695880, 828158, 48576, '<td valign="top">Great idea!  good layout and look.  The background colours all seem a slight bit different though.</td>', 'Great idea!  good layout and look.  The background colours all seem a slight bit different though.', '2009-10-21 15:20:43.000000', NULL, 1),
(5695882, 828469, 48576, '<td valign="top">Good layout and great colour.  Top 2 are a little soft for my taste, though.</td>', 'Good layout and great colour.  Top 2 are a little soft for my taste, though.', '2009-10-21 15:21:24.000000', NULL, 1),
(5695884, 828661, 48576, '<td valign="top">Great colour and feel.  This one stands out!</td>', 'Great colour and feel.  This one stands out!', '2009-10-21 15:21:48.000000', NULL, 1),
