(5696815, 828548, 75618, '<td valign="top">Really cool shot(s)</td>', 'Really cool shot(s)', '2009-10-22 04:11:08.000000', NULL, 1),
(5696822, 828824, 48086, '<td valign="top">the lighting kills this shot, its too flat. Moreover little details like the top of the pictures showing white, and the fact that the stripes are not aligned properly dont help. I personally would like to see the stripes alternating in the second shot with the 1st and 3rd. The view from above is also not too inspiring, as it lacks a 3d impact.</td>', 'the lighting kills this shot, its too flat. Moreover little details like the top of the pictures showing white, and the fact that the stripes are not aligned properly dont help. I personally would like to see the stripes alternating in the second shot with the 1st and 3rd. The view from above is also not too inspiring, as it lacks a 3d impact.', '2009-10-22 04:31:20.000000', NULL, 1),
(5696824, 828158, 69368, '<td valign="top">I love frogs, I love this shot! A winner in my eyes!</td>', 'I love frogs, I love this shot! A winner in my eyes!', '2009-10-22 04:35:18.000000', NULL, 1),
(5696825, 828681, 69368, '<td valign="top">beautiful color-composition</td>', 'beautiful color-composition', '2009-10-22 04:36:16.000000', NULL, 1),
(5696829, 828820, 69368, '<td valign="top">love the naturally colors.Especially like the photo of the squirrell: very nice focus here.</td>', 'love the naturally colors.Especially like the photo of the squirrell: very nice focus here.', '2009-10-22 04:41:50.000000', NULL, 1),
