(5697078, 828810, 102534, '<td valign="top">There are a lot of amazing entries in this week''s challenge but this one has totally blown me away. 11 if i could :)</td>', 'There are a lot of amazing entries in this week''s challenge but this one has totally blown me away. 11 if i could :)', '2009-10-22 11:26:15.000000', NULL, 1),
(5697090, 828471, 74911, '<td valign="top">I love the golden tones. Great fit for triptych challenge.</td>', 'I love the golden tones. Great fit for triptych challenge.', '2009-10-22 11:37:13.000000', NULL, 1),
(5697093, 828492, 74911, '<td valign="top">Each of these images are beauties on their own. Only complaint I have is that, I could not see those two beautiful shots bigger. But, you cannot help it for this challenge. This is just great and one of my few favs in this challenge.</td>', 'Each of these images are beauties on their own. Only complaint I have is that, I could not see those two beautiful shots bigger. But, you cannot help it for this challenge. This is just great and one of my few favs in this challenge.', '2009-10-22 11:38:25.000000', NULL, 1),
(5697094, 828406, 74911, '<td valign="top">Great capture of emotions and expressions. Amazing lighting. Having tried a couple of times with my 3 year old, I completely understand the difficulty in getting kids shots right.<br/> <br/>Raj</td>', 'Great capture of emotions and expressions. Amazing lighting. Having tried a couple of times with my 3 year old, I completely understand the difficulty in getting kids shots right. Raj', '2009-10-22 11:39:12.000000', NULL, 1),
(5697095, 828731, 74911, '<td valign="top">Great timing.</td>', 'Great timing.', '2009-10-22 11:39:31.000000', NULL, 1),
(5697096, 828786, 74911, '<td valign="top">Getting 3 different owl shots with that great detail and perfection is a real deal. And also you have managed to get all of them look at your camera. <br/> <br/>Raj</td>', 'Getting 3 different owl shots with that great detail and perfection is a real deal. And also you have managed to get all of them look at your camera.  Raj', '2009-10-22 11:40:21.000000', NULL, 1),
(5697098, 828158, 74911, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2009-10-22 11:40:33.000000', NULL, 1),
(5697099, 828102, 74911, '<td valign="top">Very clever. I can appreciate the efforts it would have taken to get this to perfection. One of the few favs I have in this challenge.</td>', 'Very clever. I can appreciate the efforts it would have taken to get this to perfection. One of the few favs I have in this challenge.', '2009-10-22 11:41:01.000000', NULL, 1),
(5697100, 828700, 74911, '<td valign="top">Brilliant setup and great results.</td>', 'Brilliant setup and great results.', '2009-10-22 11:41:15.000000', NULL, 1),
(5697102, 828634, 74911, '<td valign="top">Whether you win this challenge or not, you have already got a winning shot for the couple to keep this all their life and cherish. Great shot.</td>', 'Whether you win this challenge or not, you have already got a winning shot for the couple to keep this all their life and cherish. Great shot.', '2009-10-22 11:41:54.000000', NULL, 1),
