INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5697106, 828234, 74911, '<td valign="top">A different view at triptych. Great results.</td>', 'A different view at triptych. Great results.', '2009-10-22 11:42:40.000000', NULL, 1),
(5697107, 828045, 74911, '<td valign="top">Good timing. Don''t know how many attempts it took to get this right. But great results.</td>', 'Good timing. Don''t know how many attempts it took to get this right. But great results.', '2009-10-22 11:43:37.000000', NULL, 1),
(5697108, 828810, 74911, '<td valign="top">Great series of silhouettes.</td>', 'Great series of silhouettes.', '2009-10-22 11:43:54.000000', NULL, 1),
(5697111, 828740, 74911, '<td valign="top">Out of the three, I like the airplane shot best. In the train shot, the sky is blown out. I can understand that it is possible in an overcast day, which you can''t help it with basic editing. In the automobile shot, the roadwork cones are slightly distracting.</td>', 'Out of the three, I like the airplane shot best. In the train shot, the sky is blown out. I can understand that it is possible in an overcast day, which you can''t help it with basic editing. In the automobile shot, the roadwork cones are slightly distracting.', '2009-10-22 11:45:25.000000', NULL, 1),
(5697112, 827994, 74911, '<td valign="top">Great series. Funny too!</td>', 'Great series. Funny too!', '2009-10-22 11:45:58.000000', NULL, 1),
