INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5703126, 828483, 30982, '<td valign="top">Glad you missed on your prediction but what the heck is this doing way down here?  My favorite of the challenge - excellent "story", very well composed.</td>', 'Glad you missed on your prediction but what the heck is this doing way down here?  My favorite of the challenge - excellent "story", very well composed.', '2009-10-28 01:34:17.000000', NULL, 0),
(5703129, 827792, 30982, '<td valign="top">VERY clever and well done.  Nice thinking and execution on this!</td>', 'VERY clever and well done.  Nice thinking and execution on this!', '2009-10-28 01:34:42.000000', NULL, 0),
(5703134, 828504, 30982, '<td valign="top">This is priceless!!  One of my highest vote-getters in this challenge - not only are all the individual shots wonderful, but putting them together like this really, really works.  Excellent work.</td>', 'This is priceless!!  One of my highest vote-getters in this challenge - not only are all the individual shots wonderful, but putting them together like this really, really works.  Excellent work.', '2009-10-28 01:36:27.000000', NULL, 0),
(5703137, 828277, 30982, '<td valign="top">Love this - very nicely done.  I especially like the shallow DOF and low angle on the main shot.  Perfect for this challenge!</td>', 'Love this - very nicely done.  I especially like the shallow DOF and low angle on the main shot.  Perfect for this challenge!', '2009-10-28 01:37:15.000000', NULL, 0),
(5703144, 828744, 30982, '<td valign="top">Very clever and very fun!!</td>', 'Very clever and very fun!!', '2009-10-28 01:38:50.000000', NULL, 0),
(5703148, 828829, 30982, '<td valign="top">I thought this was quite clever and darned cute.  DPC ain''t fond of "toys" but hey, this one is better than most in my opinion!  Nicely done with the changing numbers as well.</td>', 'I thought this was quite clever and darned cute.  DPC ain''t fond of "toys" but hey, this one is better than most in my opinion!  Nicely done with the changing numbers as well.', '2009-10-28 01:40:24.000000', NULL, 0),
(5703157, 828740, 30982, '<td valign="top">I really quite liked this - knew right off what you were going for when it opened in voting.  Love your notes - it''s always somewhat reassuring to know that someone else finds these whole challenge things supremely frustrating at times, yet still perseveres!!  :-)</td>', 'I really quite liked this - knew right off what you were going for when it opened in voting.  Love your notes - it''s always somewhat reassuring to know that someone else finds these whole challenge things supremely frustrating at times, yet still perseveres!!  :-)', '2009-10-28 01:42:37.000000', NULL, 0),
(5703162, 828708, 30982, '<td valign="top">Well I thought it was pretty clever - probably a bit subtle (or possibly disturbing!) for the DPC crowd.  :-)</td>', 'Well I thought it was pretty clever - probably a bit subtle (or possibly disturbing!) for the DPC crowd.  :-)', '2009-10-28 01:43:29.000000', NULL, 0),
(5703168, 828746, 30982, '<td valign="top">I had no problem with these "going together" at all - I thought it worked just fine!!  It was one of my 7''s - I quite enjoy the shot.  Nicely seen and I love the top shot of the turkey.  Oh!  Just saw that you got the Posthumous Red!  CONGRATS!!  :-)</td>', 'I had no problem with these "going together" at all - I thought it worked just fine!!  It was one of my 7''s - I quite enjoy the shot.  Nicely seen and I love the top shot of the turkey.  Oh!  Just saw that you got the Posthumous Red!  CONGRATS!!  :-)', '2009-10-28 01:44:57.000000', NULL, 0),
(5703189, 828700, 52549, '<td valign="top">Brilliant shot! You worked hard for this, I''m delighted for you that it paid off. Many congrats on the blue, Chris.</td>', 'Brilliant shot! You worked hard for this, I''m delighted for you that it paid off. Many congrats on the blue, Chris.', '2009-10-28 01:49:08.000000', NULL, 0),
