INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5707207, 828801, 39850, '<td valign="top"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/35000-39999/39850/800/Copyrighted_Image_Reuse_Prohibited_809051.jpg"/> <br/> <br/><u>Critique Club Critique</u> <br/> <br/><b>First Impressions</b> <br/>Ah good, I get a Triptych one.<br/> <br/>I remember this one and admiring the uniqueness of it, it was also interesting to look at.  I gave this a 6.<br/> <br/><b>Photograph Information, Technicals &amp; Composition Review</b> <br/>There seems to be a slight yellowish tinge to the images, which may have something to do with your settings.  Perhaps adjusting them just a fraction, as the somewhat muted colors do work, in my opinion.  Image selection wise: it would have been nice to see a little more clarity and detail in the middle image, perhaps even a little closer cropped.  The fishing reel perhaps cropped out, not sure.  I only noticed that this time around and didn''t pick it up during voting.  My first thought on seeing it this time was that it detracted.<br/> <br/>As mentioned above, the images are interesting, especially the story that they tell, also the visible ''HYDRO...'', etc.  A bit of work, but a slight perspective correction in image #1 perhaps, to get the water level straightened.  Overall a little more clarity and detail in all the images, some of the darker areas seem to have been lost, perhaps as a result of using curves/general post processing.<br/> <br/>The black borders perhaps compete a little too much for attention with the images and the subtlety of some of the elements within them.<br/> <br/><b>Comments, Score &amp; Placement Review</b> <br/>74/145 is a ''fair'' score.  5.68 is a decent enough score.<br/> <br/>An average of 6.0 from your commenters: you received some good comments, one especially so, and helpful.<br/> <br/><b>Summary</b> <br/>For three very busy images, this still works.  Just some finer post processing and this would have had a little extra, in my opinion.</td>', '  Critique Club Critique  First Impressions Ah good, I get a Triptych one. I remember this one and admiring the uniqueness of it, it was also interesting to look at.  I gave this a 6. Photograph Information, Technicals & Composition Review There seems to be a slight yellowish tinge to the images, which may have something to do with your settings.  Perhaps adjusting them just a fraction, as the somewhat muted colors do work, in my opinion.  Image selection wise: it would have been nice to see a little more clarity and detail in the middle image, perhaps even a little closer cropped.  The fishing reel perhaps cropped out, not sure.  I only noticed that this time around and didn''t pick it up during voting.  My first thought on seeing it this time was that it detracted. As mentioned above, the images are interesting, especially the story that they tell, also the visible ''HYDRO...'', etc.  A bit of work, but a slight perspective correction in image #1 perhaps, to get the water level straightened.  Overall a little more clarity and detail in all the images, some of the darker areas seem to have been lost, perhaps as a result of using curves/general post processing. The black borders perhaps compete a little too much for attention with the images and the subtlety of some of the elements within them. Comments, Score & Placement Review 74/145 is a ''fair'' score.  5.68 is a decent enough score. An average of 6.0 from your commenters: you received some good comments, one especially so, and helpful. Summary For three very busy images, this still works.  Just some finer post processing and this would have had a little extra, in my opinion.', '2009-10-31 07:34:38.000000', NULL, 0),
(5707420, 828618, 87278, '<td valign="top">Picture = 1000 words!<br/>One of my favs this week.</td>', 'Picture = 1000 words!One of my favs this week.', '2009-10-31 14:57:34.000000', NULL, 0),
